<?php
session_start();require '../includes/db_connect.php';require_once '../includes/evaluation_conflicts.php';
if($_SERVER['REQUEST_METHOD']!=='POST'||!isset($_SESSION['logged_in'])||!in_array($_SESSION['role']??'', ['External_Admin','Super_Admin'],true)){header('Location: ../admin_login.php');exit;}
$declaration_id=(int)($_POST['declaration_id']??0);$target=(int)($_POST['evaluator_id']??0);$reason=trim((string)($_POST['reason']??''));$actor=(int)$_SESSION['user_id'];$base=$_SESSION['role']==='External_Admin'?'../external_admin/':'../super_admin/';
try{if(mb_strlen($reason)<10)throw new RuntimeException('A reassignment reason of at least 10 characters is required.');$pdo->beginTransaction();$q=$pdo->prepare("SELECT d.*,ea.EvaluatorID OldEvaluatorID,a.ScholarshipID,s.CreatedBy,creator.Organization CreatorOrg FROM evaluation_conflict_declarations d JOIN evaluation_assignments ea ON ea.AssignmentID=d.AssignmentID JOIN application a ON a.ApplicationID=d.ApplicationID JOIN scholarship s ON s.ScholarshipID=a.ScholarshipID LEFT JOIN users creator ON creator.UserID=s.CreatedBy WHERE d.DeclarationID=? AND d.ResolutionStatus='Pending Reassignment' FOR UPDATE");$q->execute([$declaration_id]);$d=$q->fetch(PDO::FETCH_ASSOC);if(!$d)throw new RuntimeException('Pending conflict declaration not found.');if($_SESSION['role']==='External_Admin'&&(int)$d['CreatedBy']!==$actor)throw new RuntimeException('Only the scholarship owner or Super Admin may reassign this case.');$u=$pdo->prepare("SELECT UserID,Organization FROM users WHERE UserID=? AND Role='External_Admin' AND AccountStatus='Active'");$u->execute([$target]);$new=$u->fetch(PDO::FETCH_ASSOC);if(!$new||$target===(int)$d['OldEvaluatorID'])throw new RuntimeException('Select a different active external evaluator.');if($_SESSION['role']==='External_Admin'&&(trim((string)$new['Organization'])===''||trim((string)$d['CreatorOrg'])===''||strcasecmp(trim((string)$new['Organization']),trim((string)$d['CreatorOrg']))!==0))throw new RuntimeException('External providers may only reassign within their organization.');$pdo->prepare("UPDATE evaluation_assignments SET AssignmentStatus='Reassigned',EndedAt=COALESCE(EndedAt,NOW()) WHERE AssignmentID=?")->execute([$d['AssignmentID']]);$pdo->prepare("INSERT INTO evaluation_assignments (ApplicationID,EvaluatorID,AssignedBy,AssignmentReason) VALUES (?,?,?,?)")->execute([$d['ApplicationID'],$target,$actor,$reason]);$new_assignment=(int)$pdo->lastInsertId();$pdo->prepare("UPDATE evaluation_conflict_declarations SET ResolutionStatus='Reassigned',ReassignedTo=?,ResolvedBy=?,ResolvedAt=NOW() WHERE DeclarationID=?")->execute([$target,$actor,$declaration_id]);logAudit($pdo,$actor,'Evaluator Reassigned',"Application #{$d['ApplicationID']} reassigned from evaluator #{$d['OldEvaluatorID']} to #$target; new assignment #$new_assignment. Reason: $reason");$pdo->commit();$_SESSION['success']='Evaluator reassigned and recorded in the audit log.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}
header('Location: '.$base.'evaluation_conflicts.php');exit;
